#!/bin/bash
# DOFEK rant v3. vo/take3.wav is the master clock; every talking shot was
# generated by wan2_7 from the slice of that take it speaks, so frame 0 of a
# shot is the first sample of its slice. Cut points are absolute FRAME numbers
# derived from the audio, so rounding never accumulates. Face shots are cut
# away from on their internal pauses, because this model keeps the mouth
# moving through silence and a held face shot shows it.
set -e
R=/tmp/claude-0/-home-user-SHOPIFY/06af39bb-792a-5cc6-a4be-ecbf44972499/scratchpad/rant
A=/tmp/claude-0/-home-user-SHOPIFY/06af39bb-792a-5cc6-a4be-ecbf44972499/scratchpad/anim/clips
cd $R; S=seg4; rm -rf $S; mkdir -p $S
V="scale=1080:1920:force_original_aspect_ratio=increase,crop=1080:1920,fps=24,setsar=1"
sg () { ffmpeg -y -loglevel error -ss $2 -i $1 -vf "$V" -frames:v $3 -an \
  -c:v libx264 -crf 18 -preset veryfast -pix_fmt yuv420p $S/$4.mp4; }
# slow push-in, non-accumulating form (z=min(k*zoom,..) silently does nothing)
sgz () { ffmpeg -y -loglevel error -ss $2 -i $1 \
  -vf "$V,zoompan=z='1+0.00085*on':d=1:x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':s=1080x1920:fps=24,setsar=1" \
  -frames:v $3 -an -c:v libx264 -crf 18 -preset veryfast -pix_fmt yuv420p $S/$4.mp4; }
#   source      in     frames  out      film in-out     what
sg  cl/Y1.mp4   0        53    p01   #   0.00- 2.21  hook, tight
sgz cl/Y2.mp4   0       116    p02   #   2.21- 7.04  wide, pointing, slow push
sg  cl/Y3.mp4   0       102    p03   #   7.04-11.29  brace, foot on block
sg  $A/c11.mp4  0.4      27    p04   #  11.29-12.42  brace on the knee, on "מגן הברך של דופק"
sg  $A/c10.mp4  0.00     55    p05   #  12.42-14.71  "ולחזור ללכת כמו בן אדם"
sg  $A/c02.mp4  0.60     39    p06   #  14.71-16.33  "לא כמו חיה פצועה"
sg  $A/c01.mp4  0.45     71    p07   #  16.33-19.29  "לא נמאס לך ללכת לעבודה ולסבול"
sg  $A/c03.mp4  0.30     60    p08   #  19.29-21.79  sidelined while the young one works
sg  $A/c05.mp4  0.30     60    p09   #  21.79-24.29  a one-minute walk is an event
sgz cl/Y4.mp4   0        87    p10   #  24.29-27.92  "די די כבר", slow push
sg  cl/Y5.mp4   0        33    p11   #  27.92-29.29  "רוצה פתרון"
sg  $A/c07.mp4  0.40     40    p12   #  29.29-30.96  the button, on "תלחץ פה"
sg  cl/Y6.mp4   0        70    p13   #  30.96-33.88  warm close
ffmpeg -y -loglevel error -framerate 24 -i t/endseq/f%04d.png -vf "fps=24,setsar=1" -frames:v 60 -an \
  -c:v libx264 -crf 18 -preset veryfast -pix_fmt yuv420p $S/p14.mp4
cd $S; : > list.txt
for f in p01 p02 p03 p04 p05 p06 p07 p08 p09 p10 p11 p12 p13 p14; do echo "file '$f.mp4'" >> list.txt; done
ffmpeg -y -loglevel error -f concat -safe 0 -i list.txt -c copy ../base4.mp4
cd ..; echo -n "base frames: "; ffprobe -v error -count_frames -show_entries stream=nb_read_frames -of csv=p=0 base4.mp4
